mapper.select:
select m.id, m.day_name, m.day_target, m.day_type, m.remind_type, m.repeat_flag, m.notify_status, m.next_notify_time, m.user_id, u.user_name, u.user_code from mes_msg_day_matter m left join mes_msg_user u on m.user_id = u.id and u.deleted_flag = '0'
m.deleted_flag = '0'
and m.id = #{param.id}
and m.day_name like concat('%', #{param.dayName}, '%')
and m.day_type = #{param.dayType}
and m.user_id = #{param.userId}
order by m.next_notify_time desc
